"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[81867],{80396(e,o,n){n.r(o),n.d(o,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>r,metadata:()=>a,toc:()=>l});const a=JSON.parse('{"id":"cursos/solid/modulos/solid-en-react/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfC\xf3mo se relaciona SOLID con la metodolog\xeda \\"Atomic Design\\" de Brad Frost (2013)? Investig\xe1 la jerarqu\xeda \xe1tomos \u2192 mol\xe9culas \u2192 organismos \u2192 templates \u2192 p\xe1ginas y c\xf3mo cada nivel se alinea con SRP, ISP y OCP en componentes React.","source":"@site/docs/cursos/solid/modulos/08-solid-en-react/cuestionario.md","sourceDirName":"cursos/solid/modulos/08-solid-en-react","slug":"/cursos/solid/modulos/solid-en-react/cuestionario","permalink":"/sasf-temarios/cursos/solid/modulos/solid-en-react/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/solid/modulos/solid-en-react/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/solid/modulos/solid-en-react/ejercicio"}}');var s=n(74848),i=n(28453);const r={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},c=void 0,t={},l=[{value:"2. [Investigar] \xbfC\xf3mo se relaciona SOLID con la metodolog\xeda &quot;Atomic Design&quot; de Brad Frost (2013)? Investig\xe1 la jerarqu\xeda \xe1tomos \u2192 mol\xe9culas \u2192 organismos \u2192 templates \u2192 p\xe1ginas y c\xf3mo cada nivel se alinea con SRP, ISP y OCP en componentes React.",id:"2-investigar-c\xf3mo-se-relaciona-solid-con-la-metodolog\xeda-atomic-design-de-brad-frost-2013-investig\xe1-la-jerarqu\xeda-\xe1tomos--mol\xe9culas--organismos--templates--p\xe1ginas-y-c\xf3mo-cada-nivel-se-alinea-con-srp-isp-y-ocp-en-componentes-react",level:3},{value:"3. [Investigar] React Server Components (RSC, 2023) introducen un nuevo modelo de ejecuci\xf3n donde los componentes pueden ser exclusivamente del servidor. \xbfC\xf3mo afecta esto a los principios SOLID, especialmente SRP y DIP? \xbfQui\xe9n es el &quot;actor&quot; que puede solicitar cambios en un Server Component vs un Client Component?",id:"3-investigar-react-server-components-rsc-2023-introducen-un-nuevo-modelo-de-ejecuci\xf3n-donde-los-componentes-pueden-ser-exclusivamente-del-servidor-c\xf3mo-afecta-esto-a-los-principios-solid-especialmente-srp-y-dip-qui\xe9n-es-el-actor-que-puede-solicitar-cambios-en-un-server-component-vs-un-client-component",level:3},{value:"4. [Investigar] \xbfC\xf3mo implementa el framework SolidJS (Ryan Carniato, 2018) los principios de reactividad fina, y qu\xe9 relaci\xf3n tiene esto con SOLID? \xbfEs una coincidencia que se llame &quot;Solid&quot; o hay una filosof\xeda de dise\xf1o detr\xe1s?",id:"4-investigar-c\xf3mo-implementa-el-framework-solidjs-ryan-carniato-2018-los-principios-de-reactividad-fina-y-qu\xe9-relaci\xf3n-tiene-esto-con-solid-es-una-coincidencia-que-se-llame-solid-o-hay-una-filosof\xeda-de-dise\xf1o-detr\xe1s",level:3},{value:"5. [Conectar] La clase muestra React Context + custom hooks como implementaci\xf3n de DIP. Investig\xe1 el patr\xf3n &quot;Functional Core, Imperative Shell&quot; (Gary Bernhardt, 2012) y explic\xe1 c\xf3mo se relaciona con DIP y SRP en aplicaciones React.",id:"5-conectar-la-clase-muestra-react-context--custom-hooks-como-implementaci\xf3n-de-dip-investig\xe1-el-patr\xf3n-functional-core-imperative-shell-gary-bernhardt-2012-y-explic\xe1-c\xf3mo-se-relaciona-con-dip-y-srp-en-aplicaciones-react",level:3},{value:"6. [Conectar] Relacion\xe1 los Render Props y Higher-Order Components (HOCs) que se mencionan en clase con el principio OCP. \xbfSon los HOCs la aplicaci\xf3n de OCP en React mediante decoraci\xf3n? \xbfPor qu\xe9 la comunidad React migr\xf3 de HOCs a hooks para implementar extensibilidad?",id:"6-conectar-relacion\xe1-los-render-props-y-higher-order-components-hocs-que-se-mencionan-en-clase-con-el-principio-ocp-son-los-hocs-la-aplicaci\xf3n-de-ocp-en-react-mediante-decoraci\xf3n-por-qu\xe9-la-comunidad-react-migr\xf3-de-hocs-a-hooks-para-implementar-extensibilidad",level:3},{value:"7. [Conectar] \xbfC\xf3mo se relaciona SOLID con el patr\xf3n &quot;Container/Presentational&quot; de Dan Abramov (2015)? Este patr\xf3n separaba componentes en &quot;containers&quot; (l\xf3gica) y &quot;presentational&quot; (UI). \xbfEs esto SRP aplicado a React? \xbfPor qu\xe9 Abramov luego dijo que este patr\xf3n est\xe1 obsoleto con la llegada de hooks?",id:"7-conectar-c\xf3mo-se-relaciona-solid-con-el-patr\xf3n-containerpresentational-de-dan-abramov-2015-este-patr\xf3n-separaba-componentes-en-containers-l\xf3gica-y-presentational-ui-es-esto-srp-aplicado-a-react-por-qu\xe9-abramov-luego-dijo-que-este-patr\xf3n-est\xe1-obsoleto-con-la-llegada-de-hooks",level:3},{value:"8. [Cuestionar] \xbfTiene sentido aplicar SOLID en React, un paradigma funcional con composici\xf3n de funciones? Investig\xe1 la postura de desarrolladores que argumentan que SOLID es un &quot;olor a OOP&quot; forzado en React y que los patrones funcionales (composici\xf3n, currying, HOF) ya resuelven los mismos problemas sin el vocabulario SOLID.",id:"8-cuestionar-tiene-sentido-aplicar-solid-en-react-un-paradigma-funcional-con-composici\xf3n-de-funciones-investig\xe1-la-postura-de-desarrolladores-que-argumentan-que-solid-es-un-olor-a-oop-forzado-en-react-y-que-los-patrones-funcionales-composici\xf3n-currying-hof-ya-resuelven-los-mismos-problemas-sin-el-vocabulario-solid",level:3},{value:"9. [Cuestionar] \xbfConducen los &quot;custom hooks&quot; a una explosi\xf3n de abstracciones que viola YAGNI y complica el c\xf3digo sin beneficio? Investig\xe1 el fen\xf3meno de &quot;over-hooking&quot; donde cada peque\xf1a l\xf3gica se convierte en un hook reusable que solo se usa una vez.",id:"9-cuestionar-conducen-los-custom-hooks-a-una-explosi\xf3n-de-abstracciones-que-viola-yagni-y-complica-el-c\xf3digo-sin-beneficio-investig\xe1-el-fen\xf3meno-de-over-hooking-donde-cada-peque\xf1a-l\xf3gica-se-convierte-en-un-hook-reusable-que-solo-se-usa-una-vez",level:3},{value:"10. [Cuestionar] \xbfEs el Context API de React realmente DIP o es un &quot;Service Locator&quot; glorificado? Compar\xe1 con la inyecci\xf3n por props (prop drilling) y evalu\xe1 si Context API introduce acoplamiento impl\xedcito que viola DIP de una forma diferente a la que resuelve.",id:"10-cuestionar-es-el-context-api-de-react-realmente-dip-o-es-un-service-locator-glorificado-compar\xe1-con-la-inyecci\xf3n-por-props-prop-drilling-y-evalu\xe1-si-context-api-introduce-acoplamiento-impl\xedcito-que-viola-dip-de-una-forma-diferente-a-la-que-resuelve",level:3}];function d(e){const o={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(o.h3,{id:"2-investigar-c\xf3mo-se-relaciona-solid-con-la-metodolog\xeda-atomic-design-de-brad-frost-2013-investig\xe1-la-jerarqu\xeda-\xe1tomos--mol\xe9culas--organismos--templates--p\xe1ginas-y-c\xf3mo-cada-nivel-se-alinea-con-srp-isp-y-ocp-en-componentes-react",children:'2. [Investigar] \xbfC\xf3mo se relaciona SOLID con la metodolog\xeda "Atomic Design" de Brad Frost (2013)? Investig\xe1 la jerarqu\xeda \xe1tomos \u2192 mol\xe9culas \u2192 organismos \u2192 templates \u2192 p\xe1ginas y c\xf3mo cada nivel se alinea con SRP, ISP y OCP en componentes React.'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),": Brad Frost propuso Atomic Design como metodolog\xeda para construir interfaces. La relaci\xf3n con SOLID: ",(0,s.jsx)(o.strong,{children:"\xc1tomos"})," (button, input, label): son componentes de una sola responsabilidad (SRP puro). Cada \xe1tomo recibe props m\xednimas (ISP). Variaciones de un \xe1tomo se logran con props, no con herencia (OCP: ",(0,s.jsx)(o.code,{children:'variant="primary" | "secondary"'})," en lugar de ",(0,s.jsx)(o.code,{children:"PrimaryButton extends Button"}),"). ",(0,s.jsx)(o.strong,{children:"Mol\xe9culas"})," (SearchBar = input + button): componen \xe1tomos, cada mol\xe9cula tiene una responsabilidad compuesta (SRP a nivel de mol\xe9cula). No heredan de \xe1tomos \u2014 composici\xf3n pura (LSP no aplica). ",(0,s.jsx)(o.strong,{children:"Organismos"}),' (Header = logo + nav + searchbar): orquestan mol\xe9culas, se comportan como "componentes contenedor" en React. ',(0,s.jsx)(o.strong,{children:"Templates"}),": layout sin datos reales \u2014 ISP a nivel de p\xe1gina (no reciben datos que no renderizan). ",(0,s.jsx)(o.strong,{children:"P\xe1ginas"}),": templates con datos reales, donde se inyectan servicios (DIP a nivel de p\xe1gina). Atomic Design implementa SOLID en el frontend: cada nivel tiene una responsabilidad definida, las interfaces entre niveles son props (ISP), la extensi\xf3n se hace por composici\xf3n (OCP), y los servicios se inyectan en las p\xe1ginas (DIP). La jerarqu\xeda fuerza a pensar en granularidad de responsabilidades \u2014 un \xe1tomo no puede ser un organismo, y viceversa."]}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),": Frost no dise\xf1\xf3 Atomic Design con SOLID en mente, pero hay un isomorfismo natural: SRP produce \xe1tomos cohesivos, ISP produce \xe1tomos con props m\xednimas, OCP produce mol\xe9culas extensibles por composici\xf3n. La metodolog\xeda de Frost es una implementaci\xf3n pr\xe1ctica de SOLID en dise\xf1o de UI."]}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"3-investigar-react-server-components-rsc-2023-introducen-un-nuevo-modelo-de-ejecuci\xf3n-donde-los-componentes-pueden-ser-exclusivamente-del-servidor-c\xf3mo-afecta-esto-a-los-principios-solid-especialmente-srp-y-dip-qui\xe9n-es-el-actor-que-puede-solicitar-cambios-en-un-server-component-vs-un-client-component",children:'3. [Investigar] React Server Components (RSC, 2023) introducen un nuevo modelo de ejecuci\xf3n donde los componentes pueden ser exclusivamente del servidor. \xbfC\xf3mo afecta esto a los principios SOLID, especialmente SRP y DIP? \xbfQui\xe9n es el "actor" que puede solicitar cambios en un Server Component vs un Client Component?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),": RSC divide los componentes en dos categor\xedas con modelos de ejecuci\xf3n diferentes: ",(0,s.jsx)(o.strong,{children:"Server Components"}),": se ejecutan solo en el servidor, pueden acceder a BD y sistema de archivos directamente, no tienen estado interactivo. ",(0,s.jsx)(o.strong,{children:"Client Components"}),": se ejecutan en el navegador, tienen estado, efectos y eventos. Impacto en SOLID: ",(0,s.jsx)(o.strong,{children:"SRP"}),": RSC fuerza una separaci\xf3n de responsabilidades radical: los componentes de datos (server) y los componentes interactivos (client) son naturalmente segregados. Un Server Component ",(0,s.jsx)(o.code,{children:"UserProfile"})," que obtiene datos de la BD tiene un solo actor (backend/data team). Un Client Component ",(0,s.jsx)(o.code,{children:"UserProfileEditor"}),' que maneja interacci\xf3n tiene otro actor (UX team). La l\xednea "use client" es un marcador de SRP expl\xedcito. ',(0,s.jsx)(o.strong,{children:"DIP"}),': los Server Components pueden acceder directamente a BD sin abstracciones (fetch desde el servidor no requiere mock para tests), lo que PARECE violar DIP pero en realidad la "dependencia de infraestructura" es natural porque el servidor ES infraestructura. Para testing, se mockea la capa de datos (server actions), no el componente. ',(0,s.jsx)(o.strong,{children:"ISP"}),": los Server Components t\xedpicamente retornan datos serializados (solo props), lo que naturalmente produce interfaces m\xednimas. ",(0,s.jsx)(o.strong,{children:"OCP"}),": RSC + Server Actions permiten agregar nuevas operaciones al servidor sin modificar componentes cliente existentes. En resumen, RSC hace que SRP y DIP sean m\xe1s naturales porque el entorno de ejecuci\xf3n fuerza la separaci\xf3n de responsabilidades y la inversi\xf3n de dependencias es inherente (el cliente no sabe c\xf3mo el servidor obtiene los datos)."]}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),': El equipo de React (Dan Abramov, Andrew Clark) dise\xf1\xf3 RSC para resolver problemas de waterfall de datos y bundle size, pero incidentalmente produjo una arquitectura m\xe1s alineada con SOLID: la separaci\xf3n server/client es una separaci\xf3n por "actor" (SRP), y la comunicaci\xf3n es por props serializadas (ISP).']}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"4-investigar-c\xf3mo-implementa-el-framework-solidjs-ryan-carniato-2018-los-principios-de-reactividad-fina-y-qu\xe9-relaci\xf3n-tiene-esto-con-solid-es-una-coincidencia-que-se-llame-solid-o-hay-una-filosof\xeda-de-dise\xf1o-detr\xe1s",children:'4. [Investigar] \xbfC\xf3mo implementa el framework SolidJS (Ryan Carniato, 2018) los principios de reactividad fina, y qu\xe9 relaci\xf3n tiene esto con SOLID? \xbfEs una coincidencia que se llame "Solid" o hay una filosof\xeda de dise\xf1o detr\xe1s?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),': SolidJS no se llama as\xed por SOLID, sino por el principio de "solid reactivity" (reactividad s\xf3lida/precisa). Sin embargo, hay alineaciones filos\xf3ficas: ',(0,s.jsx)(o.strong,{children:"SRP"}),': SolidJS fomenta "primitives" (createSignal, createEffect, createResource) como unidades at\xf3micas de reactividad. Cada primitive tiene una responsabilidad \xfanica, a diferencia de React donde ',(0,s.jsx)(o.code,{children:"useEffect"})," puede hacer m\xfaltiples cosas. ",(0,s.jsx)(o.strong,{children:"OCP"}),': el modelo de "stores" de Solid (createStore) con proxies permite extender el estado sin modificar componentes. Los componentes son funciones puras que reciben props. ',(0,s.jsx)(o.strong,{children:"DIP"}),': Solid no tiene un contenedor IoC, pero su ecosistema fomenta pasar "primitives" como dependencias \u2014 ',(0,s.jsx)(o.code,{children:"function UserList(&#x7B; getUserList &#x7D;)"})," donde ",(0,s.jsx)(o.code,{children:"getUserList"})," es una funci\xf3n, no una implementaci\xf3n concreta. ",(0,s.jsx)(o.strong,{children:"LSP"}),": como no hay herencia de clases (todo son funciones), LSP se manifiesta en que cualquier funci\xf3n que cumpla la firma esperada es sustituible \u2014 tipado estructural, no nominal. ",(0,s.jsx)(o.strong,{children:"ISP"}),': los componentes reciben solo las props que usan (fine-grained reactivity: si una prop no se usa, no se re-renderiza). La conexi\xf3n real con SOLID: SolidJS fue dise\xf1ado con los principios de "composici\xf3n sobre herencia" y "reactividad declarativa", que son congruentes con SOLID aunque no fue expl\xedcitamente inspirado por Martin. El nombre es coincidencia, pero la filosof\xeda de dise\xf1o subyacente converge.']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),": Ryan Carniato ha hablado sobre patrones de dise\xf1o en SolidJS (en su blog y charlas). Aunque no usa el vocabulario SOLID expl\xedcitamente, los principios de reactividad fina, composici\xf3n declarativa y separaci\xf3n de responsabilidades son an\xe1logos funcionales a SRP, OCP y DIP."]}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"5-conectar-la-clase-muestra-react-context--custom-hooks-como-implementaci\xf3n-de-dip-investig\xe1-el-patr\xf3n-functional-core-imperative-shell-gary-bernhardt-2012-y-explic\xe1-c\xf3mo-se-relaciona-con-dip-y-srp-en-aplicaciones-react",children:'5. [Conectar] La clase muestra React Context + custom hooks como implementaci\xf3n de DIP. Investig\xe1 el patr\xf3n "Functional Core, Imperative Shell" (Gary Bernhardt, 2012) y explic\xe1 c\xf3mo se relaciona con DIP y SRP en aplicaciones React.'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),': "Functional Core, Imperative Shell" (Bernhardt, "Boundaries", 2012) propone dividir la aplicaci\xf3n en: ',(0,s.jsx)(o.strong,{children:"Functional Core"}),": l\xf3gica pura \u2014 funciones que reciben datos y retornan decisiones, sin efectos secundarios. Todo es determinista y testeable sin mocks. ",(0,s.jsx)(o.strong,{children:"Imperative Shell"}),": capa externa que realiza efectos secundarios (HTTP, localStorage, DOM) y llama al functional core con los datos obtenidos. La relaci\xf3n con DIP en React: (1) El Functional Core ES la abstracci\xf3n (DIP): define qu\xe9 operaciones necesita (interfaces/promesas). (2) El Imperative Shell ES la implementaci\xf3n concreta (DIP): implementa las operaciones reales. (3) En un componente React, los hooks ser\xedan el Imperative Shell (llaman al functional core con datos y despachan resultados). Ejemplo: ",(0,s.jsx)(o.code,{children:"function calculateDiscount(order: Order): number"})," (Functional Core, SRP puro). El hook ",(0,s.jsx)(o.code,{children:"useOrder()"})," (Imperative Shell) obtiene la orden v\xeda fetch, llama a ",(0,s.jsx)(o.code,{children:"calculateDiscount"}),", y retorna el resultado. El componente solo renderiza. Conexi\xf3n con SRP: Functional Core tiene una sola responsabilidad (c\xe1lculo puro). Imperative Shell tiene una sola responsabilidad (manejar efectos). El componente tiene una sola responsabilidad (renderizar). Es SRP + DIP integrados: el m\xf3dulo de alto nivel (Functional Core) no depende de infraestructura; el m\xf3dulo de bajo nivel (Imperative Shell) implementa las operaciones."]}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),": Bernhardt present\xf3 este patr\xf3n como una arquitectura para testeabilidad, y es directamente an\xe1logo a DIP: la l\xf3gica de negocio (= abstracci\xf3n) no depende de efectos secundarios (= detalles). En React, esto se traduce a hooks como shell, funciones puras como core."]}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"6-conectar-relacion\xe1-los-render-props-y-higher-order-components-hocs-que-se-mencionan-en-clase-con-el-principio-ocp-son-los-hocs-la-aplicaci\xf3n-de-ocp-en-react-mediante-decoraci\xf3n-por-qu\xe9-la-comunidad-react-migr\xf3-de-hocs-a-hooks-para-implementar-extensibilidad",children:"6. [Conectar] Relacion\xe1 los Render Props y Higher-Order Components (HOCs) que se mencionan en clase con el principio OCP. \xbfSon los HOCs la aplicaci\xf3n de OCP en React mediante decoraci\xf3n? \xbfPor qu\xe9 la comunidad React migr\xf3 de HOCs a hooks para implementar extensibilidad?"}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),": Ambos implementan OCP: (1) ",(0,s.jsx)(o.strong,{children:"HOCs"}),": ",(0,s.jsx)(o.code,{children:"withAuth(MyComponent)"})," envuelve un componente agregando comportamiento de autenticaci\xf3n sin modificar ",(0,s.jsx)(o.code,{children:"MyComponent"})," \u2014 el componente original est\xe1 cerrado, el HOC extiende. El patr\xf3n Decorator llevado a React. (2) ",(0,s.jsx)(o.strong,{children:"Render Props"}),": ",(0,s.jsx)(o.code,{children:'&#x3C;DataFetcher url="/api/users" render=&#x7B;(data) => &#x3C;UserList data=&#x7B;data&#x7D; />&#x7D; />'})," \u2014 ",(0,s.jsx)(o.code,{children:"DataFetcher"})," est\xe1 cerrado, el render prop extiende. \xbfPor qu\xe9 la migraci\xf3n a hooks? (a) ",(0,s.jsx)(o.strong,{children:"Wrapper hell"}),": m\xfaltiples HOCs anidados (",(0,s.jsx)(o.code,{children:"withAuth(withTheme(withRouter(MyComponent)))"}),') producen jerarqu\xedas dif\xedciles de depurar y props que vienen "de la nada". (b) ',(0,s.jsx)(o.strong,{children:"Nombres de props colisionan"}),": dos HOCs pueden inyectar props con el mismo nombre. (c) ",(0,s.jsx)(o.strong,{children:"Static composition"}),": los HOCs se aplican en tiempo de definici\xf3n, no en runtime. Los hooks permiten composici\xf3n din\xe1mica dentro del componente. (d) ",(0,s.jsx)(o.strong,{children:"SRP m\xe1s claro"}),": un hook tiene una responsabilidad (",(0,s.jsx)(o.code,{children:"useAuth()"}),"), un HOC puede mezclar varias (inconveniente para SRP). Los hooks implementan OCP de forma m\xe1s granular: en lugar de envolver el componente, el componente compone hooks usando los que necesita. ",(0,s.jsx)(o.code,{children:"function Dashboard() &#x7B; const auth = useAuth(); const theme = useTheme(); ... &#x7D;"})," \u2014 cada hook es una extensi\xf3n que se agrega al componente sin modificar su estructura de props. La migraci\xf3n HOC \u2192 hooks es OCP + ISP: los hooks son role interfaces (ISP), mientras los HOCs eran header interfaces (inyectaban todas las props juntas)."]}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),": La comunidad React (Dan Abramov, Sophie Alpert) identific\xf3 que HOCs violaban ISP indirectamente al mezclar props inyectadas. Los hooks resuelven esto: cada hook expone una interfaz espec\xedfica (ISP), y el componente elige exactamente qu\xe9 hooks usar (OCP por composici\xf3n)."]}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"7-conectar-c\xf3mo-se-relaciona-solid-con-el-patr\xf3n-containerpresentational-de-dan-abramov-2015-este-patr\xf3n-separaba-componentes-en-containers-l\xf3gica-y-presentational-ui-es-esto-srp-aplicado-a-react-por-qu\xe9-abramov-luego-dijo-que-este-patr\xf3n-est\xe1-obsoleto-con-la-llegada-de-hooks",children:'7. [Conectar] \xbfC\xf3mo se relaciona SOLID con el patr\xf3n "Container/Presentational" de Dan Abramov (2015)? Este patr\xf3n separaba componentes en "containers" (l\xf3gica) y "presentational" (UI). \xbfEs esto SRP aplicado a React? \xbfPor qu\xe9 Abramov luego dijo que este patr\xf3n est\xe1 obsoleto con la llegada de hooks?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),": Abramov propuso en 2015 separar componentes en dos tipos: ",(0,s.jsx)(o.strong,{children:"Container Components"}),": manejan l\xf3gica (fetching, estado, c\xe1lculos) y pasan datos a presentacionales. ",(0,s.jsx)(o.strong,{children:"Presentational Components"}),': reciben props y renderizan UI. Esto es SRP puro: un componente tiene una sola responsabilidad (presentar o contener). Un container puede tener m\xfaltiples razones para cambiar (si maneja l\xf3gica de m\xfaltiples fuentes), pero al menos la separaci\xf3n b\xe1sica est\xe1 hecha. Abramov declar\xf3 este patr\xf3n obsoleto con hooks (2019) porque: (a) Los hooks permiten que cualquier componente funcional tenga estado y efectos sin ser una clase. La distinci\xf3n container/presentational era en parte una necesidad t\xe9cnica (class components vs functional stateless components). (b) Con hooks, un componente puede ser "presentational" y usar ',(0,s.jsx)(o.code,{children:"useContext"}),' sin convertirse en "container". (c) La tendencia actual es "un hook por responsabilidad" \u2014 cada hook encapsula una l\xf3gica; el componente compone hooks y renderiza. Esto es un refinamiento de SRP: en lugar de "containers grandes que manejan toda la l\xf3gica", ten\xe9s "hooks peque\xf1os que manejan una responsabilidad cada uno". La relaci\xf3n con SOLID: Container/Presentational = SRP grueso (1 container con N responsabilidades). Hooks = SRP fino (N hooks con 1 responsabilidad cada uno). La evoluci\xf3n muestra que la comunidad React refin\xf3 SRP a granularidad m\xe1s fina con hooks.']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),': Abramov explic\xf3 esta evoluci\xf3n en su blog overreacted.io (2019). Los hooks no invalidan SRP; lo refinan. La separaci\xf3n de responsabilidades sigue siendo el objetivo, pero la unidad de separaci\xf3n pas\xf3 de "componente" a "hook".']}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"8-cuestionar-tiene-sentido-aplicar-solid-en-react-un-paradigma-funcional-con-composici\xf3n-de-funciones-investig\xe1-la-postura-de-desarrolladores-que-argumentan-que-solid-es-un-olor-a-oop-forzado-en-react-y-que-los-patrones-funcionales-composici\xf3n-currying-hof-ya-resuelven-los-mismos-problemas-sin-el-vocabulario-solid",children:'8. [Cuestionar] \xbfTiene sentido aplicar SOLID en React, un paradigma funcional con composici\xf3n de funciones? Investig\xe1 la postura de desarrolladores que argumentan que SOLID es un "olor a OOP" forzado en React y que los patrones funcionales (composici\xf3n, currying, HOF) ya resuelven los mismos problemas sin el vocabulario SOLID.'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),": Cr\xedticos como Michel Weststrate (creador de MobX) y Eric Elliott argumentan que: (1) ",(0,s.jsx)(o.strong,{children:"SRP = funciones peque\xf1as"}),': la programaci\xf3n funcional ya tiene el principio de "funciones peque\xf1as que hacen una sola cosa". No necesit\xe1s SRP; necesit\xe1s "small pure functions". (2) ',(0,s.jsx)(o.strong,{children:"OCP = higher-order functions"}),": en lugar de crear una interfaz ",(0,s.jsx)(o.code,{children:"Strategy"})," con implementaciones, pas\xe1 una funci\xf3n. OCP en FP es trivial: ",(0,s.jsx)(o.code,{children:"const result = calculate(fn, data)"}),". La estrategia es ",(0,s.jsx)(o.code,{children:"fn"}),". (3) ",(0,s.jsx)(o.strong,{children:"LSP = type system"}),": el tipado estructural de TypeScript garantiza sustituibilidad sin herencia. Si un objeto tiene ",(0,s.jsx)(o.code,{children:"fly(): void"}),", es sustituible \u2014 no necesita una jerarqu\xeda de clases. (4) ",(0,s.jsx)(o.strong,{children:"ISP = props typing"}),": TypeScript ya fuerza que cada componente declare exactamente las props que necesita \u2014 ISP est\xe1 en el sistema de tipos, no en el dise\xf1o. (5) ",(0,s.jsx)(o.strong,{children:"DIP = dependency injection via closures"}),": en lugar de inyectar una interfaz, inyect\xe1s una funci\xf3n. El closure captura la implementaci\xf3n concreta. La cr\xedtica es que SOLID trae vocabulario y patrones OOP (interfaces, herencia, polimorfismo) a un ecosistema que ya tiene soluciones funcionales m\xe1s simples. ",(0,s.jsx)(o.strong,{children:"Defensa"}),': SOLID como principios (no como implementaci\xf3n OOP) s\xed aplican a React. SRP como "un hook = una responsabilidad", OCP como "componentes extensibles por composici\xf3n", DIP como "hooks que reciben funciones en lugar de llamar a fetch". El error es copiar la implementaci\xf3n OOP (interfaces, Strategy Pattern con clases) en lugar de aplicar la INTENCI\xd3N de SOLID con herramientas funcionales (hooks, HOF, closures).']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),": Weststrate y Elliott no est\xe1n en contra de los objetivos de SOLID (bajo acoplamiento, alta cohesi\xf3n, extensibilidad). Est\xe1n en contra del mecanismo OOP para lograrlos en un paradigma funcional. React + TypeScript permiten cumplir los objetivos de SOLID con menos ceremonias usando el sistema de tipos y funciones."]}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"9-cuestionar-conducen-los-custom-hooks-a-una-explosi\xf3n-de-abstracciones-que-viola-yagni-y-complica-el-c\xf3digo-sin-beneficio-investig\xe1-el-fen\xf3meno-de-over-hooking-donde-cada-peque\xf1a-l\xf3gica-se-convierte-en-un-hook-reusable-que-solo-se-usa-una-vez",children:'9. [Cuestionar] \xbfConducen los "custom hooks" a una explosi\xf3n de abstracciones que viola YAGNI y complica el c\xf3digo sin beneficio? Investig\xe1 el fen\xf3meno de "over-hooking" donde cada peque\xf1a l\xf3gica se convierte en un hook reusable que solo se usa una vez.'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),': El "over-hooking" es un anti-patr\xf3n React documentado por Kent C. Dodds y otros: crear ',(0,s.jsx)(o.code,{children:"useUserName(user)"})," (1 l\xednea de c\xf3digo), ",(0,s.jsx)(o.code,{children:"useUserEmail(user)"})," (1 l\xednea), etc., para cumplir SRP/ISP dogm\xe1ticamente. Los problemas: (1) ",(0,s.jsx)(o.strong,{children:"Explosi\xf3n de archivos"}),": 30 hooks en 30 archivos que antes eran 30 l\xedneas en un componente. (2) ",(0,s.jsx)(o.strong,{children:"Indirecci\xf3n innecesaria"}),": seguir el flujo de datos requiere saltar entre 10 archivos de hooks. (3) ",(0,s.jsx)(o.strong,{children:"YAGNI"}),': hooks creados "por si se reutilizan" y nunca reutilizados. (4) ',(0,s.jsx)(o.strong,{children:"Falsa cohesi\xf3n"}),": hooks que parecen cohesivos por nombre pero que en realidad son un solo caso de uso fragmentado artificialmente. ",(0,s.jsx)(o.strong,{children:"L\xedmite saludable seg\xfan la comunidad"}),": (a) extra\xe9 un hook cuando la l\xf3gica tiene AL MENOS 10 l\xedneas y es no trivial (fetching, c\xe1lculos, suscripciones). (b) Extra\xe9 cuando el hook SE REUTILIZA en al menos 2 componentes. (c) No extraigas cuando el hook solo envuelve un ",(0,s.jsx)(o.code,{children:"useState"}),' (1 l\xednea de indirecci\xf3n no justifica un archivo). (d) El test: \xbfsi muevo esta l\xf3gica a un hook, puedo probarla aisladamente? Si la respuesta es no (porque la l\xf3gica solo tiene sentido en el contexto del componente), no la extraigas. Kent C. Dodds: "un hook no es un refugio para cualquier l\xf3gica; es una abstracci\xf3n. Y las abstracciones tienen un costo".']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),': La comunidad React pas\xf3 de "todo en el componente" (2016) a "todo en hooks" (2019) y ahora se estabiliza en un equilibrio (2023+). La regla de Dodds "colocate until it hurts" (manten\xe9 la l\xf3gica junta hasta que duela la duplicaci\xf3n) es la ant\xedtesis del over-hooking dogm\xe1tico.']}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"10-cuestionar-es-el-context-api-de-react-realmente-dip-o-es-un-service-locator-glorificado-compar\xe1-con-la-inyecci\xf3n-por-props-prop-drilling-y-evalu\xe1-si-context-api-introduce-acoplamiento-impl\xedcito-que-viola-dip-de-una-forma-diferente-a-la-que-resuelve",children:'10. [Cuestionar] \xbfEs el Context API de React realmente DIP o es un "Service Locator" glorificado? Compar\xe1 con la inyecci\xf3n por props (prop drilling) y evalu\xe1 si Context API introduce acoplamiento impl\xedcito que viola DIP de una forma diferente a la que resuelve.'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),": Context API est\xe1 m\xe1s cerca de un Service Locator que de Dependency Injection verdadera. Argumentos: (1) ",(0,s.jsx)(o.strong,{children:"Dependencia impl\xedcita"}),": ",(0,s.jsx)(o.code,{children:"const userService = useContext(UserContext)"})," \u2014 la dependencia no est\xe1 declarada en los props del componente. No pod\xe9s saber qu\xe9 necesita el componente mirando su firma. Esto es EXACTAMENTE la cr\xedtica que se le hace a Service Locator. (2) ",(0,s.jsx)(o.strong,{children:"Acoplamiento al Context"}),": el componente se acopla al Context espec\xedfico (no a una interfaz general). Si cambi\xe1s ",(0,s.jsx)(o.code,{children:"UserContext"})," por ",(0,s.jsx)(o.code,{children:"AuthContext"}),", ten\xe9s que modificar el componente. Con DI verdadera (inyecci\xf3n por props), el componente recibe el servicio sin saber de d\xf3nde viene. (3) ",(0,s.jsx)(o.strong,{children:"Testing"}),": necesit\xe1s envolver el componente en un Provider para testearlo \u2014 igual que necesit\xe1s configurar un Service Locator. Con inyecci\xf3n por props, pas\xe1s el mock directamente. ",(0,s.jsx)(o.strong,{children:"Pero Context API tambi\xe9n tiene ventajas sobre Service Locator tradicional"}),": (a) El acoplamiento es expl\xedcito en el \xe1rbol de componentes (el Provider es visible en el JSX). (b) TypeScript tipa el contexto \u2014 no hay b\xfasqueda por string como en Service Locator cl\xe1sico. (c) Pod\xe9s tener m\xfaltiples Providers del mismo tipo en diferentes partes del \xe1rbol. ",(0,s.jsx)(o.strong,{children:"Comparaci\xf3n"}),": Prop drilling = DI verdadera (dependencias expl\xedcitas, visibles en props). Context API = Service Locator mejorado (dependencias impl\xedcitas pero type-safe). El DIP ideal en React ser\xeda: el componente recibe el servicio por props (DI), y el padre lo obtiene del Context (Service Locator localizado en el padre). As\xed el componente es DIP puro (depende de la abstracci\xf3n inyectada) y el padre se encarga del wiring."]}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),': La comunidad React debate esto activamente. Dan Abramov reconoce que Context es "DI para el \xe1rbol de componentes", pero advierte contra usarlo para todo. La inyecci\xf3n por props hace DIP expl\xedcito; Context lo hace conveniente pero menos visible.']})]})}function u(e={}){const{wrapper:o}={...(0,i.R)(),...e.components};return o?(0,s.jsx)(o,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,o,n){n.d(o,{R:()=>r,x:()=>c});var a=n(96540);const s={},i=a.createContext(s);function r(e){const o=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(o):{...o,...e}},[o,e])}function c(e){let o;return o=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),a.createElement(i.Provider,{value:o},e.children)}}}]);